  "motionAtlas.feedback-refinement.bindingExamples.0.sourceText":
    "In a fictional writing review, the note to name the next step changes Share update to Review the draft before the message is ready to share.",
  "motionAtlas.feedback-refinement.category": "Iterative work",
  "motionAtlas.feedback-refinement.controls.artifactLabel": "Artifact label",
  "motionAtlas.feedback-refinement.controls.finalLabel": "Final label",
