  "motionAtlas.repeating-blocks-to-table.tags.2": "repeating sections",
  "motionAtlas.repeating-blocks-to-table.tags.3": "schema recovery",
  "motionAtlas.repeating-blocks-to-table.useWhen":
    "Expose tabular structure inside repeated prose sections.",
