  "motionAtlas.serviceable-panel-swap.bindingExamples.0.sourceText":
    "In a fictional modular console, a maintainer replaces the control unit through its service opening. The input and output modules remain unchanged, and the removed control remains visible.",
  "motionAtlas.serviceable-panel-swap.category": "Resilience and maintenance",
  "motionAtlas.serviceable-panel-swap.controls.enclosure": "enclosure",
