  "motionAtlas.travel-time-network-frontier.control.nodes": "nodes",
  "motionAtlas.travel-time-network-frontier.control.originId": "originId",
  "motionAtlas.travel-time-network-frontier.control.roads": "roads",
  "motionAtlas.travel-time-network-frontier.control.showCosts":
    "Show shortest costs and edge minutes.",
  "motionAtlas.travel-time-network-frontier.control.toId": "toId",
