  "motionAtlas.grouped-value-picker.creativeDirection": [
    "960x600 React/SVG, shared palette, deterministic 180 frames at 30fps. Frames 0-12 reveal the scene. Frames 13-55 place observations on an ordered rail. Frames 56-105 reveal the selected rule: first highlights the first tile; most-frequent stacks equal values; numeric rules fold values onto one calculation line. Frames 106-139 attach the derived result without erasing the rail. Hold the resolved meaning during frames 140-165. Frames 166-179 return to the same opaque ground for a six-second loop; reset is editorial.",
  ],
  "motionAtlas.grouped-value-picker.default.labels.countUnit": ["observations"],
  "motionAtlas.grouped-value-picker.default.labels.entity": [
    "Fictional Site A",
  ],
  "motionAtlas.grouped-value-picker.default.labels.field": ["Recorded items"],
  "motionAtlas.grouped-value-picker.default.labels.missing": ["Missing"],
  "motionAtlas.grouped-value-picker.default.labels.result": ["Derived field"],
  "motionAtlas.grouped-value-picker.default.labels.unit": ["items"],
  "motionAtlas.grouped-value-picker.description": [
    "Several observations for one entity line up in their recorded order. An explicit aggregation rule selects or calculates the one value shown on the entity record, with the original observations retained.",
  ],
  "motionAtlas.grouped-value-picker.distinction": [
    "Field-conflict-choice chooses among authored alternatives by human decision. This calculates a deterministic field from repeated observations under a stated rule, preserving order and missingness.",
  ],
  "motionAtlas.grouped-value-picker.domains.0": ["Editorial illustration"],
  "motionAtlas.grouped-value-picker.goodFor.0": [
    "Explain first, mode and aggregate field selection",
  ],
  "motionAtlas.grouped-value-picker.goodFor.1": [
    "Compare missing-value policies in case records",
  ],
  "motionAtlas.grouped-value-picker.intent": [
    "Make a field aggregation rule and its missing-value semantics explicit.",
  ],
  "motionAtlas.grouped-value-picker.motionBeats.0": [
    "Place observations on their recorded-order rail.",
  ],
  "motionAtlas.grouped-value-picker.motionBeats.1": [
    "Select the first, stack equal values or fold a numeric calculation.",
  ],
  "motionAtlas.grouped-value-picker.motionBeats.2": [
    "Attach the result while retaining the source rail.",
  ],
  "motionAtlas.grouped-value-picker.motionBeats.3": [
    "Hold the resolved meaning.",
  ],
  "motionAtlas.grouped-value-picker.name": [
    "Say how repeated observations become one value",
  ],
  "motionAtlas.grouped-value-picker.notFor.0": [
    "No rule is inherently correct for a real domain; choosing the rule is an author responsibility.",
  ],
  "motionAtlas.grouped-value-picker.notFor.1": [
    "Null policy is explicit and must not silently change between views.",
  ],
  "motionAtlas.grouped-value-picker.notFor.2": [
    "No real product screen, external fetch, supplied code execution, or measured performance claim. All text is authored; no JSX, functions or URLs in props.",
  ],
  "motionAtlas.grouped-value-picker.notFor.3": [
    "Count uses labels.countUnit; first, mode, sum, mean, min and max use labels.unit for non-null results. Null uses labels.missing. Mean is calculated exactly as sum/non-null count; display rounds to two decimals with a visible approximation mark when rounding changes the value. No rounded intermediate feeds another calculation.",
  ],
  "motionAtlas.grouped-value-picker.notFor.4": [
    "Supplied prose is preserved. Fictional framing, source completeness and agreement between labels and structured state are author responsibilities. Runtime validation enforces structural bounds and exact cross-field rules.",
  ],
  "motionAtlas.grouped-value-picker.notFor.5": [
    "Literal IDs and row values preserve exact whitespace using visible whitespace marks at a fixed readable size.",
  ],
  "motionAtlas.grouped-value-picker.prompt": [
    "Make a field aggregation rule and its missing-value semantics explicit.",
  ],
