  "motionAtlas.invalid-table-quarantine.creativeDirection": [
    "960x600 React/SVG, shared palette, deterministic 180 frames at 30fps. Frames 0-12 reveal the scene. Frames 13-45 close a visible read shutter before altering one row. Frames 46-95 show the authored mutation outcome with an invalid band still covering the table. Frames 96-139 either insert a full replacement sheet and reopen the shutter, or retain the closed shutter. Hold the resolved meaning during frames 140-165. Frames 166-179 return to the same opaque ground for a six-second loop; reset is editorial.",
  ],
  "motionAtlas.invalid-table-quarantine.default.labels.blocked": [
    "Read blocked",
  ],
  "motionAtlas.invalid-table-quarantine.default.labels.invalid": [
    "Invalid until complete reload",
  ],
  "motionAtlas.invalid-table-quarantine.default.labels.readable": ["Readable"],
  "motionAtlas.invalid-table-quarantine.default.labels.reload": [
    "Complete reload",
  ],
  "motionAtlas.invalid-table-quarantine.description": [
    "A stored table is marked invalid before a mutation starts. If the operation fails, a read cannot use the partial contents; a complete replacement restores readability.",
  ],
  "motionAtlas.invalid-table-quarantine.distinction": [
    "Unlike revision-restore, the point is refusing reads of potentially partial state. It is not a rollback: only a complete reload clears invalidity.",
  ],
  "motionAtlas.invalid-table-quarantine.domains.0": ["Editorial illustration"],
  "motionAtlas.invalid-table-quarantine.goodFor.0": [
    "Explain why failed partial writes must block reads",
  ],
  "motionAtlas.invalid-table-quarantine.goodFor.1": [
    "Show invalidation before mutation and complete reload recovery",
  ],
  "motionAtlas.invalid-table-quarantine.intent": [
    "Keep potentially partial state out of later reads.",
  ],
  "motionAtlas.invalid-table-quarantine.motionBeats.0": [
    "Close reads before altering a row.",
  ],
  "motionAtlas.invalid-table-quarantine.motionBeats.1": [
    "Retain invalidity through the authored mutation outcome.",
  ],
  "motionAtlas.invalid-table-quarantine.motionBeats.2": [
    "Replace the complete sheet before reopening, or keep reads blocked.",
  ],
  "motionAtlas.invalid-table-quarantine.motionBeats.3": [
    "Hold the resolved meaning.",
  ],
  "motionAtlas.invalid-table-quarantine.name": [
    "Keep partial data out of the next read",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.0": [
    "Reload is authored, not automatic recovery evidence.",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.1": [
    "A completed mutation remains invalid until reload under this contract.",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.2": [
    "The shutter represents validity, not encryption or deletion.",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.3": [
    "No real product screen, external fetch, supplied code execution, or measured performance claim. All text is authored; no JSX, functions or URLs in props.",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.4": [
    "Supplied prose is preserved. Fictional framing, source completeness and agreement between labels and structured state are author responsibilities. Runtime validation enforces structural bounds and exact cross-field rules.",
  ],
  "motionAtlas.invalid-table-quarantine.notFor.5": [
    "Literal IDs and row values preserve exact whitespace using visible whitespace marks at a fixed readable size.",
  ],
  "motionAtlas.invalid-table-quarantine.prompt": [
    "Keep potentially partial state out of later reads.",
  ],
