  "motionAtlas.resumable-byte-transfer.creativeDirection": [
    "960x600 React/SVG, shared palette, deterministic 180 frames at 30fps. Frames 0-12 reveal the scene. Frames 13-55 transfer chunks to the acknowledged boundary. Frames 56-90 interrupt one unacknowledged segment without adding it to confirmed progress. Frames 91-139 restart at the confirmed offset and append the remaining chunks. Hold the resolved meaning during frames 140-165. Frames 166-179 return to the same opaque ground for a six-second loop; reset is editorial.",
  ],
  "motionAtlas.resumable-byte-transfer.default.file.label": [
    "Fictional table file",
  ],
  "motionAtlas.resumable-byte-transfer.default.labels.confirmed": [
    "Confirmed prefix",
  ],
  "motionAtlas.resumable-byte-transfer.default.labels.remaining": [
    "Still pending",
  ],
  "motionAtlas.resumable-byte-transfer.default.labels.retry": ["Resume here"],
  "motionAtlas.resumable-byte-transfer.default.labels.unit": ["bytes"],
  "motionAtlas.resumable-byte-transfer.description": [
    "A bounded file strip crosses in chunks. After an interruption, the sender resumes at the stored acknowledgment offset while the already confirmed prefix stays in place.",
  ],
  "motionAtlas.resumable-byte-transfer.distinction": [
    "Retry-backoff repeats whole attempts. This retains a confirmed prefix and resumes by byte offset, so interruption does not restart the entire file.",
  ],
  "motionAtlas.resumable-byte-transfer.domains.0": ["Editorial illustration"],
  "motionAtlas.resumable-byte-transfer.file.controls.label": ["label"],
  "motionAtlas.resumable-byte-transfer.goodFor.0": [
    "Explain resumable file uploads by acknowledged offset",
  ],
  "motionAtlas.resumable-byte-transfer.goodFor.1": [
    "Distinguish confirmed bytes from in-flight bytes",
  ],
  "motionAtlas.resumable-byte-transfer.intent": [
    "Distinguish confirmed progress from work that must be retransmitted.",
  ],
  "motionAtlas.resumable-byte-transfer.motionBeats.0": [
    "Transfer the exact acknowledged prefix.",
  ],
  "motionAtlas.resumable-byte-transfer.motionBeats.1": [
    "Interrupt an unacknowledged chunk without confirming it.",
  ],
  "motionAtlas.resumable-byte-transfer.motionBeats.2": [
    "Resume from the stored boundary and append exact chunks.",
  ],
  "motionAtlas.resumable-byte-transfer.motionBeats.3": [
    "Hold the resolved relationship.",
  ],
  "motionAtlas.resumable-byte-transfer.name": [
    "Continue after the acknowledged byte",
  ],
  "motionAtlas.resumable-byte-transfer.notFor.0": [
    "Confirmed means acknowledged in this authored protocol, not independently verified integrity.",
  ],
  "motionAtlas.resumable-byte-transfer.notFor.1": [
    "No compression ratio, transfer speed or duration is measured.",
  ],
  "motionAtlas.resumable-byte-transfer.notFor.2": [
    "Final short chunk uses exact remaining bytes.",
  ],
  "motionAtlas.resumable-byte-transfer.notFor.3": [
    "No real product screen, external fetch, supplied code execution, or measured performance claim. All text is authored; no JSX, functions or URLs in props.",
  ],
  "motionAtlas.resumable-byte-transfer.notFor.4": [
    "Supplied prose is preserved. Fictional framing, evidence and agreement between wording and selected states are authoring responsibilities. Runtime validation enforces structural bounds and explicit cross-field rules.",
  ],
  "motionAtlas.resumable-byte-transfer.prompt": [
    "Distinguish confirmed progress from work that must be retransmitted.",
  ],
