  "motionAtlas.retry-backoff.aliases.0": ["Time and resilience"],
  "motionAtlas.retry-backoff.bindingExamples.0.sourceText": [
    "In this fictional request sequence, the first retry waits one second, the next waits two seconds, and the third attempt returns the sample.",
  ],
  "motionAtlas.retry-backoff.category": ["Time and resilience"],
  "motionAtlas.retry-backoff.controls.attempts": ["attempts"],
  "motionAtlas.retry-backoff.controls.attempts.help": [
    "Defines every attempt, its outcome, and the waiting interval before the next attempt. 3..4 attempts; labels <= 16 characters; nonfinal outcomes must be retry; nonfinal delayAfter integers 1..16 and strictly increasing across nonfinal attempts; final outcome complete or stop with delayAfter 0",
  ],
  "motionAtlas.retry-backoff.controls.complete": ["complete"],
  "motionAtlas.retry-backoff.controls.delayAfter": ["delayAfter"],
  "motionAtlas.retry-backoff.controls.delayUnit": ["delayUnit"],
