  "motionAtlas.retry-backoff.controls.showDelayValues": ["showDelayValues"],
  "motionAtlas.retry-backoff.controls.showDelayValues.help": [
    "Shows the supplied waits as values in addition to proportional brackets. boolean",
  ],
  "motionAtlas.retry-backoff.controls.stop": ["stop"],
  "motionAtlas.retry-backoff.controls.wait": ["wait"],
  "motionAtlas.retry-backoff.creativeDirection": [
    "Frames 12..36 introduce the operation token and its first attempt marker. The token makes a short out-and-back trip for each retry outcome, then traverses a visibly wider waiting bracket before the next attempt. Bracket widths are proportional to the authored delay values, while the full action is compressed into frames 36..140. At the final marker, the token either docks in a completed socket or rests against a stop cap. Hold the final outcome and the complete chain of attempts through frame 168, then fade to ground. The growing gaps, not repeated flashes, explain the backoff.",
  ],
  "motionAtlas.retry-backoff.default.attempts.0.label": ["Attempt 1"],
  "motionAtlas.retry-backoff.default.attempts.1.label": ["Attempt 2"],
  "motionAtlas.retry-backoff.default.attempts.2.label": ["Attempt 3"],
